-- Storage buckets and access rules (product pictures, expense documents) and the sign-up trigger.
insert into storage.buckets (id, name, public, file_size_limit) values ('product-images','product-images',true,5242880),('operix-expense-documents','operix-expense-documents',false,20971520) on conflict (id) do nothing;
create policy product_images_delete on storage.objects as PERMISSIVE for DELETE to authenticated using (((bucket_id = 'product-images'::text) AND (((split_part(name, '/'::text, 1) = 'company'::text) AND (split_part(name, '/'::text, 2) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) AND can_access_company((split_part(name, '/'::text, 2))::uuid)) OR ((split_part(name, '/'::text, 1) = 'user'::text) AND (split_part(name, '/'::text, 2) = (( SELECT uid() AS uid))::text))))) ;
create policy product_images_insert on storage.objects as PERMISSIVE for INSERT to authenticated  with check (((bucket_id = 'product-images'::text) AND (((split_part(name, '/'::text, 1) = 'company'::text) AND (split_part(name, '/'::text, 2) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) AND can_access_company((split_part(name, '/'::text, 2))::uuid)) OR ((split_part(name, '/'::text, 1) = 'user'::text) AND (split_part(name, '/'::text, 2) = (( SELECT uid() AS uid))::text)))));
create policy product_images_update on storage.objects as PERMISSIVE for UPDATE to authenticated using (((bucket_id = 'product-images'::text) AND (((split_part(name, '/'::text, 1) = 'company'::text) AND (split_part(name, '/'::text, 2) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) AND can_access_company((split_part(name, '/'::text, 2))::uuid)) OR ((split_part(name, '/'::text, 1) = 'user'::text) AND (split_part(name, '/'::text, 2) = (( SELECT uid() AS uid))::text))))) with check (((bucket_id = 'product-images'::text) AND (((split_part(name, '/'::text, 1) = 'company'::text) AND (split_part(name, '/'::text, 2) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) AND can_access_company((split_part(name, '/'::text, 2))::uuid)) OR ((split_part(name, '/'::text, 1) = 'user'::text) AND (split_part(name, '/'::text, 2) = (( SELECT uid() AS uid))::text)))));
create policy rbac_expense_documents_delete on storage.objects as PERMISSIVE for DELETE to authenticated using (((bucket_id = 'operix-expense-documents'::text) AND private.has_company_permission((split_part(name, '/'::text, 1))::uuid, 'expense.manage'::text))) ;
create policy rbac_expense_documents_insert on storage.objects as PERMISSIVE for INSERT to authenticated  with check (((bucket_id = 'operix-expense-documents'::text) AND (EXISTS ( SELECT 1
   FROM expenses expense
  WHERE ((expense.company_id = (split_part(objects.name, '/'::text, 1))::uuid) AND (expense.id = (split_part(objects.name, '/'::text, 3))::uuid) AND (split_part(objects.name, '/'::text, 2) = 'expenses'::text) AND (private.rbac_can_read_resource(expense.company_id, 'expense'::text, expense.user_id, expense.assigned_user_id, 'expense.create'::text) OR private.rbac_can_read_resource(expense.company_id, 'expense'::text, expense.user_id, expense.assigned_user_id, 'expense.edit'::text)))))));
create policy rbac_expense_documents_select on storage.objects as PERMISSIVE for SELECT to authenticated using (((bucket_id = 'operix-expense-documents'::text) AND ((EXISTS ( SELECT 1
   FROM expenses expense
  WHERE ((expense.company_id = (split_part(objects.name, '/'::text, 1))::uuid) AND (expense.id = (split_part(objects.name, '/'::text, 3))::uuid) AND (split_part(objects.name, '/'::text, 2) = 'expenses'::text) AND private.rbac_can_read_resource(expense.company_id, 'expense'::text, expense.user_id, expense.assigned_user_id, 'expense.view_own'::text)))) OR private.has_company_permission((split_part(name, '/'::text, 1))::uuid, 'expense.view_all'::text)))) ;
create policy rbac_expense_documents_update on storage.objects as PERMISSIVE for UPDATE to authenticated using (((bucket_id = 'operix-expense-documents'::text) AND private.has_company_permission((split_part(name, '/'::text, 1))::uuid, 'expense.manage'::text))) with check (((bucket_id = 'operix-expense-documents'::text) AND private.has_company_permission((split_part(name, '/'::text, 1))::uuid, 'expense.manage'::text)));

-- Create a profile and workspace when someone signs up (auth.users lives in Supabase's auth schema).
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
